#[test]
fn send_and_select_move_record_via_move_uses_e3003() { for s in ["pick(ch, m) <- move m", "select {\n        pick(ch, m) <- move m => {}\n    }", "select {\n        ch <- move m => {}\n        ch <- move m => {}\n    }", "f := fn() { ch <- move m }\n    f()"] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", &format!("fn pick(c chan map[string]int, m map[string]int) chan map[string]int {{ return c }}\nfn main() {{\n    m := map[string]int{{\"a\": 1}}\n    ch := make(chan map[string]int, 1)\n    {s}\n}}\n")).unwrap()); assert!(r.diagnostics.iter().any(|d| d.code == "HYB-E3003"), "{s}: {:?}", r.diagnostics); } assert!(hy_check::check_file(&hy_syntax::parse_file("t.hy", "fn main() {\n    m := map[string]int{\"a\": 1}\n    ch := make(chan map[string]int, 1)\n    ch <- move m\n}\n").unwrap()).diagnostics.is_empty()); }
